int go(ll l, ll r, ll need, int alphSize)
{
    ll m = l + (r - l) / 2LL;
    if (need < m)
        return go(l, m - 1, need, alphSize - 1);
    else if (need > m)
        return go(m + 1, r, need, alphSize - 1);
    else
        return alphSize;
}

