int can(int len) {
    for (int i = 0; i < 8; i++)
        cur[i] = 0;
    for (int i = 0; i <= n; i++)
        for (int j = 0; j < (1 << 8); j++)
            dp[i][j] = -inf;
    dp[0][0] = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < (1 << 8); j++) {
            if (dp[i][j] == -inf)
                continue;
            for (int k = 0; k < 8; k++) {
                if (j & (1 << k))
                    continue;
                int it = cur[k] + len - 1;
                if (it >= in[k].size())
                    continue;
                amax(dp[in[k][it] + 1][j | (1 << k)], dp[i][j]);

                it++;
                if (it >= in[k].size())
                    continue;
                amax(dp[in[k][it] + 1][j | (1 << k)], dp[i][j] + 1);
            }
        }
        cur[a[i]]++;
    }

    int ans = -inf;
    for (int i = 0; i <= n; i++)
        ans = max(ans, dp[i][(1 << 8) - 1]);
    if (ans == -inf)
        return -1;

    return ans * (len + 1) + (8 - ans) * len;
}

int main() {
    for (int i = 0; i < n; i++) {
        in[a[i]].push_back(i);
    }

    int l = 1, r = n / 8;
    while (r - l > 1) {
        int m = (l + r) >> 1;
        if (can(m) != -1)
            l = m;
        else
            r = m;
    }
    int ans = max(can(l), can(r));
    if (ans == -1) {
        ans = 0;
        for (int i = 0; i < 8; i++)
            if (!in[i].empty())
                ans++;
    }
    cout << ans;
    return 0;
}
